sysauto_script.script:
// Get current date and time
var rightNow = new GlideDateTime();

// Calculate date 3 days ago
var threeDaysAgo = new GlideDateTime();
threeDaysAgo.addDaysUTC(-3);

// Query for incidents that have been on hold for 3+ days
var incidentsOnHold = new GlideRecord('incident');
incidentsOnHold.addQuery('state', 6); // On Hold state
incidentsOnHold.addQuery('sys_updated_on', '<=', threeDaysAgo);
incidentsOnHold.addQuery('active', true); // Only active incidents

incidentsOnHold.query();

// Process each incident that has been on hold for 3+ days
while(incidentsOnHold.next()){
    gs.info("Processing incident on hold for 3+ days: " + incidentsOnHold.number);

    // Generate event to close the incident and send notification
    gs.eventQueue('x_58872_needit.closeHoldIncident', incidentsOnHold, incidentsOnHold.number, gs.getUserName());
}
